static int slen(const char*s){int n=0;if(!s)return 0;while(s[n])n++;return n;} static void scpy(char*d,const char*s,int cap){int i=0;if(!d||cap<=0)return;if(s)for(;i<cap-1&&s[i];i++)d[i]=s[i];d[i]=0;} static int seq(const char*a,const char*b){int i=0;while(a[i]&&b[i]&&a[i]==b[i])i++;return a[i]==0&&b[i]==0;} static int lower(int c){return c>='A'&&c<='Z'?c+32:c;} static int contains_ci(const char*s,const char*q){if(!q||!q[0])return 1;for(int i=0;s&&s[i];i++){int j=0;while(q[j]&&s[i+j]&&lower((unsigned char)s[i+j])==lower((unsigned char)q[j]))j++;if(!q[j])return 1;}return 0;}
static int atoi2(const char*s){int sign=1,v=0;if(!s)return 0;if(*s=='-'){sign=-1;s++;}while(*s>='0'&&*s<='9'){v=v*10+(*s-'0');s++;}return sign*v;} static float atof2(const char*s){float v=0,f=.1f;int dot=0,sign=1;if(!s)return 0;if(*s=='-'){sign=-1;s++;}while(*s){if(*s=='.'){dot=1;s++;continue;}if(*s>='0'&&*s<='9'){if(!dot)v=v*10+(*s-'0');else{v+=(*s-'0')*f;f*=.1f;}}s++;}return v*sign;}
static void itoa2(int v,char*b){char rev[20];int n=0,k=0;if(v==0){b[0]='0';b[1]=0;return;}if(v<0){b[n++]='-';v=-v;}while(v){rev[k++]=(char)('0'+v%10);v/=10;}while(k)b[n++]=rev[--k];b[n]=0;} static void append(char*d,int cap,const char*s){int n=slen(d);for(int i=0;s&&s[i]&&n<cap-1;i++)d[n++]=s[i];d[n]=0;}
static DWORD hexcolor(const char*s,DWORD def){if(!s||s[0]!='#')return def;unsigned v=0;for(int i=1;i<=6&&s[i];i++){char c=s[i];unsigned n=(c>='0'&&c<='9')?c-'0':(c>='a'&&c<='f')?c-'a'+10:(c>='A'&&c<='F')?c-'A'+10:0;v=(v<<4)|n;}return RGB((v>>16)&255,(v>>8)&255,v&255);} static int hotkey_vk(){int n=8;if(g_hotkey[0]=='F')n=atoi2(g_hotkey+1);if(n<1||n>12)n=8;return VK_F1+n-1;}
