static void txtf(HDC dc,const char*s,int x,int y,int w,int h,DWORD c,UINT flags,HFONT f){if(!s||!s[0]||w<=0||h<=0)return;WCHAR ws[1024];int n=MultiByteToWideChar(CP_UTF8,0,s,-1,ws,1024);if(n<=0)return;RECT r={x,y,x+w,y+h};SetTextColor(dc,c);SetBkMode(dc,TRANSPARENT);HGDIOBJ old=0;if(f)old=SelectObject(dc,f);DrawTextW(dc,ws,-1,&r,flags|DT_NOPREFIX);if(old)SelectObject(dc,old);} static void txt(HDC dc,const char*s,int x,int y,int w,int h,DWORD c,UINT flags){txtf(dc,s,x,y,w,h,c,flags,g_font);} static void small(HDC dc,const char*s,int x,int y,int w,int h,DWORD c,UINT flags){txtf(dc,s,x,y,w,h,c,flags,g_font_small);} static void head(HDC dc,const char*s,int x,int y,int w,int h,DWORD c,UINT flags){txtf(dc,s,x,y,w,h,c,flags,g_font_head);} static void title(HDC dc,const char*s,int x,int y,int w,int h,DWORD c,UINT flags){txtf(dc,s,x,y,w,h,c,flags,g_font_title);}
