static HDC g_mdc=0;static int text_w(const char*s,HFONT f){if(!s||!s[0])return 0;if(!g_mdc)g_mdc=CreateCompatibleDC(NULL);WCHAR ws[256];int n=MultiByteToWideChar(CP_UTF8,0,s,-1,ws,256);SIZE sz={0,0};if(g_mdc&&n>1){HGDIOBJ old=f?SelectObject(g_mdc,f):0;GetTextExtentPoint32W(g_mdc,ws,n-1,&sz);if(old)SelectObject(g_mdc,old);}return sz.cx>0?sz.cx:slen(s)*9;}   /* 9 px per byte if Windows cannot measure: too wide is safe, too narrow overlaps */
