static DWORD statuscol(const char*s){if(seq(s,"Holding"))return C_GOOD;if(seq(s,"Recovering"))return C_WARN;if(seq(s,"Declining")||seq(s,"Loss pending")||seq(s,"Lost"))return C_BAD;if(contains_ci(s,"not eligible")||contains_ci(s,"invalid")||contains_ci(s,"reject")||contains_ci(s,"error")||contains_ci(s,"risk"))return C_BAD;if(contains_ci(s,"ps+ eligible")||contains_ci(s,"playstyle+ eligible")||contains_ci(s,"plus eligible"))return C_PLUS;if(contains_ci(s,"ready")||contains_ci(s,"eligible")||contains_ci(s,"acquired")||contains_ci(s,"first team"))return C_GOOD;if(contains_ci(s,"hold")||contains_ci(s,"cooldown")||contains_ci(s,"waiting")||contains_ci(s,"cap")||contains_ci(s,"attention"))return C_WARN;return C_INFO;}
