static int csv_has(const char*csv,const char*item){if(!csv||!item||!item[0])return 0;int il=slen(item);for(int i=0;csv[i];){while(csv[i]==' '||csv[i]==',')i++;int st=i;while(csv[i]&&csv[i]!=',')i++;int en=i;while(en>st&&csv[en-1]==' ')en--;if(en-st==il){int ok=1;for(int k=0;k<il;k++)if(csv[st+k]!=item[k]){ok=0;break;}if(ok)return 1;}if(csv[i]==',')i++;}return 0;}
