static int csv_count(const char*csv,const char*any);static void range_caption(char*out,int cap,const char*csv,const char*any,const char*prefix){int n=csv_count(csv,any);if(n<=0){scpy(out,any,cap);return;}scpy(out,prefix,cap);append(out,cap," ");if(n==1){append(out,cap,csv);return;}char b[16];itoa2(n,b);append(out,cap,"(");append(out,cap,b);append(out,cap," ranges)");}
