static void fp_geom(RECT*r,FpGeom*g){g->px=48;g->py=100;g->pw=r->right-96;g->ph=r->bottom-124;g->sx=g->px+20;g->sy=g->py+140;g->sw=240;g->fy=g->py+g->ph-44;g->srows=(g->fy-30-g->sy)/30;if(g->srows<1)g->srows=1;g->gx=g->sx+g->sw+24;g->gy=g->sy;g->gw=g->px+g->pw-20-g->gx;g->gh=g->fy-12-g->gy;g->cols=g->gw/112;g->rows=g->gh/128;if(g->cols<1)g->cols=1;if(g->rows<1)g->rows=1;}
static int fp_page_size(RECT*r){FpGeom g;fp_geom(r,&g);int n=g.cols*g.rows;return n<4?4:(n>60?60:n);}
/* v1.24.33: faces are one growing list; a "Load more faces" button sits under the last row. */
#define FP_SHOWN_CAP 950   /* matches faces.MAX_PICKER_FACES */
static int fp_can_more(void){return g_fp_shown<g_fp_total&&g_fp_shown<FP_SHOWN_CAP;}
static int fp_content_h(FpGeom*g){int rows=(g_face_count+g->cols-1)/g->cols;return rows*128+(fp_can_more()?60:0);}
static int fp_max_scroll(FpGeom*g){int m=fp_content_h(g)-g->gh;return m>0?m:0;}
static int fp_more_y(FpGeom*g){int rows=(g_face_count+g->cols-1)/g->cols;return g->gy+rows*128-g_fp_scroll+6;}
