static int face_picker_click(int x,int y){RECT r;GetClientRect(g_overlay,&r);FpGeom g;fp_geom(&r,&g);if(y>=g.py+18&&y<g.py+50){if(x>=g.px+g.pw-148&&x<g.px+g.pw-20){face_picker_close(1);return 1;}if(x>=g.px+g.pw-340&&x<g.px+g.pw-160){face_pick_automatic();return 1;}}if(g_fp_pid!=g_selected_pid)return 1;if(x>=g.sx&&x<g.sx+g.sw&&y>=g.sy&&y<g.sy+g.srows*30){int ri=g_fp_reg_scroll+(y-g.sy)/30;if(ri<g_fp_reg_count&&!seq(g_fp_regs[ri],g_fp_region)){scpy(g_fp_region,g_fp_regs[ri],80);scpy(g_fp_region_label,g_fp_reg_labels[ri],96);g_fp_pid=0;g_face_count=0;g_fp_scroll=0;g_fp_need_scroll=1;g_fp_loading_more=0;face_cmd("face_region",g_fp_regs[ri]);}return 1;}if(x<g.gx||y<g.gy||y>=g.gy+g.gh)return 1;if(fp_can_more()){int my=fp_more_y(&g),bx=g.gx+(g.gw-300)/2;if(y>=my&&y<my+32&&x>=bx&&x<bx+300){face_load_more();return 1;}}{int cy=y-g.gy+g_fp_scroll;int c=(x-g.gx)/112,rr=cy/128;if(c<g.cols&&(x-g.gx)%112<96&&cy%128<96){int i=rr*g.cols+c;if(i<g_face_count)face_pick(g_faces[i].rel);}}return 1;}
static void face_picker_wheel(int d){RECT r;GetClientRect(g_overlay,&r);FpGeom g;fp_geom(&r,&g);if(g_mouse_x>=g.sx&&g_mouse_x<g.sx+g.sw){int mx=g_fp_reg_count-g.srows;if(mx<0)mx=0;g_fp_reg_scroll+=d>0?-3:3;if(g_fp_reg_scroll<0)g_fp_reg_scroll=0;if(g_fp_reg_scroll>mx)g_fp_reg_scroll=mx;return;}g_fp_scroll+=d>0?-128:128;int mx=fp_max_scroll(&g);if(g_fp_scroll>mx)g_fp_scroll=mx;if(g_fp_scroll<0)g_fp_scroll=0;}
