static int path_count_kind(const char*kind,int pid){int n=0;for(int i=0;i<g_path_count;i++)if(g_paths[i].pid==pid&&seq(g_paths[i].kind,kind))n++;return n;} static PathRec* nth_path(const char*kind,int pid,int nth){int n=0;for(int i=0;i<g_path_count;i++)if(g_paths[i].pid==pid&&seq(g_paths[i].kind,kind)){if(n++==nth)return &g_paths[i];}return 0;}
/* v1.24.36: PLAYSTYLE DECLINE rows. owned = status: 0 declining, 1 recovering, 2 loss pending, 3 lost, 4 holding. */
static void decline_row(HDC dc,PathRec*q,int x,int y,int w){int st=q->owned;DWORD c=st==3?C_MUTED:(st==4?C_GOOD:(st==1?C_WARN:C_BAD));box(dc,x,y,w,72,C_PANEL2,c);small(dc,q->name,x+16,y+13,210,18,c,DT_LEFT|DT_SINGLELINE|DT_END_ELLIPSIS);small(dc,q->desc,x+16,y+33,w-510,30,C_MUTED,DT_LEFT|DT_WORDBREAK);if(st!=3){char t[48];int iv=(int)(q->pct+0.5f);itoa2(iv,t);append(t,48,"% decline");small(dc,t,x+w-460,y+16,108,18,C_MUTED,DT_RIGHT|DT_SINGLELINE);float pc=q->pct<0?0:(q->pct>100?100:q->pct);box(dc,x+w-340,y+21,200,30,C_PANEL2,C_BORDER);int fw=(int)(198*pc/100.0f);if(pc>0&&fw<3)fw=3;if(fw>0)box(dc,x+w-339,y+22,fw,28,st==1?C_WARN:C_BAD,st==1?C_WARN:C_BAD);}const char*lab=st==0?"Declining":(st==1?"Recovering":(st==2?"Loss pending":(st==3?"Lost":"Holding")));status_badge(dc,lab,x+w-128,y+21,116);}
static void path_row(HDC dc,PathRec*q,int plus,int x,int y,int w,DWORD accent){if(seq(q->kind,"DECLINE")){decline_row(dc,q,x,y,w);return;}box(dc,x,y,w,72,C_PANEL2,accent);int tx=x+16;small(dc,q->name,tx,y+13,210,18,accent,DT_LEFT|DT_SINGLELINE|DT_END_ELLIPSIS);small(dc,q->desc[0]?q->desc:(q->owned?"Owned":"Development path"),tx,y+33,w-510,30,C_MUTED,DT_LEFT|DT_WORDBREAK);char pts[48];int iv=(int)(q->value+0.5f);itoa2(iv,pts);append(pts,48," pts");small(dc,pts,x+w-430,y+16,78,18,C_MUTED,DT_RIGHT|DT_SINGLELINE);bar(dc,x+w-340,y+21,200,q->pct);status_badge(dc,q->owned?"Acquired":(q->pct>=100?"Ready":q->pct>0?"Developing":"No Progress"),x+w-128,y+21,116);}
static int draw_path_history_panel(HDC dc,Player*p,int x,int y,int w);
static int pathhist_count(const char*kind,const char*name,int pid);
static int path_expanded(PathRec*q){return seq(g_hist_kind,q->kind)&&seq(g_hist_name,q->name);}
static int path_history_height(PathRec*q){int cnt=pathhist_count(q->kind,q->name,q->pid);return cnt?72+cnt*52:112;}
/* v1.24.25: the PlayStyle / PlayStyle+ / Role++ sections can be collapsed from their header,
   or from a pinned header bar while scrolled part-way through a section. */
static int g_dev_collapsed[4],g_sec_y[4],g_sec_h[4],g_sec_abs[4],g_sticky_k=-1;
static const char*SEC_TITLES[4]={"PLAYSTYLE PATHS","PLAYSTYLE+ PATHS","ROLE++ PATHS","PLAYSTYLE DECLINE"};
static int sec_index(const char*kind){return seq(kind,"PLUS")?1:(seq(kind,"ROLE")?2:(seq(kind,"DECLINE")?3:0));}
static DWORD sec_color(int k){return k==1?C_PLUS:(k==2?C_ROLE:(k==3?C_BAD:C_INFO));}
static int draw_path_section(HDC dc,Player*p,const char*kind,const char*title_text,const char*sub,DWORD accent,int plus,int x,int y,int w,int maxrows){
 int k=sec_index(kind);g_sec_y[k]=y;g_sec_abs[k]=y+g_detail_scroll;
 if(g_dev_collapsed[k]){accent_card(dc,x,y,w,62,accent);head(dc,title_text,x+16,y+10,w-220,22,accent,DT_LEFT|DT_SINGLELINE|DT_END_ELLIPSIS);small(dc,sub,x+16,y+36,w-220,20,C_MUTED,DT_LEFT|DT_SINGLELINE|DT_END_ELLIPSIS);small(dc,">  SHOW SECTION",x+w-196,y+12,180,18,accent,DT_RIGHT|DT_SINGLELINE);g_sec_h[k]=62;return y+62;}
 int cnt=path_count_kind(kind,p->id),drawc=cnt<maxrows?cnt:maxrows,extra=0;
 int rowsh=0;for(int i=0;i<drawc;i++){PathRec*q=nth_path(kind,p->id,i);if(!q)continue;rowsh+=q->hist?100:80;if(path_expanded(q))extra+=path_history_height(q);}
 if(seq(kind,"PLUS")&&!p->pluseligible&&!p->plus[0]){drawc=0;rowsh=0;extra=0;}
 g_sec_h[k]=70+(drawc>0?rowsh+extra:44);
 accent_card(dc,x,y,w,70+(drawc>0?rowsh+extra:44),accent);head(dc,title_text,x+16,y+10,w-220,22,accent,DT_LEFT|DT_SINGLELINE|DT_END_ELLIPSIS);small(dc,sub,x+16,y+36,w-220,20,C_MUTED,DT_LEFT|DT_SINGLELINE|DT_END_ELLIPSIS);small(dc,"v  HIDE SECTION",x+w-196,y+12,180,18,accent,DT_RIGHT|DT_SINGLELINE);
 int yy=y+66;if(seq(kind,"PLUS")&&!p->pluseligible&&!p->plus[0]){small(dc,"Not eligible",x+18,yy,w-36,24,C_BAD,DT_LEFT|DT_SINGLELINE);return yy+42;}if(!cnt){small(dc,seq(kind,"PLUS")?"Eligible - no active PlayStyle+ path yet":(seq(kind,"ROLE")?"No active Role++ development paths":"No active PlayStyle paths"),x+18,yy,w-36,24,C_MUTED,DT_LEFT|DT_SINGLELINE);return yy+42;}
 for(int i=0;i<drawc;i++){PathRec*q=nth_path(kind,p->id,i);if(!q)continue;path_row(dc,q,plus,x+10,yy,w-20,accent);if(!q->hist){yy+=80;continue;}small(dc,path_expanded(q)?"v  HIDE DEVELOPMENT HISTORY":">  SHOW DEVELOPMENT HISTORY",x+24,yy+76,w-48,18,accent,DT_LEFT|DT_SINGLELINE);
 if(g_path_hit_n<128){g_path_hit_y[g_path_hit_n]=yy;g_path_hit_idx[g_path_hit_n]=(int)(q-g_paths);g_path_hit_n++;}yy+=100;if(path_expanded(q))yy=draw_path_history_panel(dc,p,x+10,yy,w-20);}
 return yy+6;
}
static int pathhist_count(const char*kind,const char*name,int pid){int n=0;for(int i=0;i<g_path_hist_count;i++)if(g_path_hist[i].pid==pid&&seq(g_path_hist[i].kind,kind)&&seq(g_path_hist[i].name,name))n++;return n;}
